from typing import Dict, List, Optional, Tuple
from collections import Counter, OrderedDict, defaultdict, deque
import heapq

def min_cost_climbing_stairs(cost: list[int]) -> int:
    a, b = cost[0], cost[1]
    for value in cost[2:]:
        a, b = b, value + min(a, b)
    return min(a, b)

